// El aviso dice QUE HACER, no solo que paso (regla del canal #alertas).
const previo = $input.first().json || {};
const sobre = $('Webhook · planeacion').first().json.body || {};
let ficha = {};
try { ficha = $('Ficha del cliente').first().json || {}; } catch (e) { ficha = {}; }
const nombre = ficha.name || sobre.client_id || '(cliente sin nombre)';
const cuando = previo.created_at ? String(previo.created_at).slice(0, 16).replace('T', ' ') : '(fecha desconocida)';
const L = [];
L.push('🔁 *Plan repetido · NO se corrió* — no se gastó nada.');
L.push('');
L.push('*Cliente:* ' + nombre);
L.push('*Ya tiene un plan* del ' + cuando);
L.push('');
L.push('*Qué hacer:*');
