L.push('    Ojo: no hay memoria entre corridas — el plan nuevo se paga entero de nuevo.');
L.push('• Si creés que el plan viejo está mal → decilo acá y lo miramos antes de repetir.');
return [{ json: {
  slack: { channel: 'C0B7XUUEBHA', text: L.join(String.fromCharCode(10)) },
  plan_previo_de: cuando,
} }];

// El cable de vuelta NO puede ser mudo. Si no volvio, la sala NUNCA se entera
// de que la corrida termino y su marca queda sin resolver: la ventana del doble
// pago quedaria cerrada solo en el papel.
const r = $input.first().json || {};
const volvio = r.ok === true;
let corr = null;
try { corr = $('Webhook · planeacion').first().json.body._sala_correlation_id || null; } catch (e) { corr = null; }
// Falla RUIDOSA solo si la sala lo despacho: un disparo a mano no tiene a quien
// contestarle, y marcar eso en rojo seria ruido.
if (corr && !volvio) {
  throw new Error('CABLE_DE_VUELTA_MUDO · la sala NO se entero de que la corrida termino · codigo ' + String(r.code || r.error || 'sin codigo'));
}
return [{ json: {
  cierre: 'plan_terminado',
  vuelta_ok: volvio,
  vuelta_detalle: volvio ? (r.event_id || 'sin event_id') : (r.code || r.detail || r.error || 'sin respuesta de la sala'),
  despachado_por_la_sala: !!corr,
} }];

// El cable de vuelta NO puede ser mudo. Si no volvio, la sala NUNCA se entera
// de que la corrida termino y su marca queda sin resolver: la ventana del doble
// pago quedaria cerrada solo en el papel.
const r = $input.first().json || {};
const volvio = r.ok === true;
let corr = null;
try { corr = $('Webhook · planeacion').first().json.body._sala_correlation_id || null; } catch (e) { corr = null; }
// Falla RUIDOSA solo si la sala lo despacho: un disparo a mano no tiene a quien
// contestarle, y marcar eso en rojo seria ruido.
if (corr && !volvio) {
  throw new Error('CABLE_DE_VUELTA_MUDO · la sala NO se entero de que la corrida termino · codigo ' + String(r.code || r.error || 'sin codigo'));
}
return [{ json: {
  cierre: 'no_corrio_repetida',
  vuelta_ok: volvio,
  vuelta_detalle: volvio ? (r.event_id || 'sin event_id') : (r.code || r.detail || r.error || 'sin respuesta de la sala'),
  despachado_por_la_sala: !!corr,
} }];

// PEGAMENTO (CC#2 · C2) · NO es una de las cinco piezas.
// `elegir brazos` (B1, de CC#3) lee LA FICHA DEL CLIENTE. Por el cable le llega
// la salida del control de corrida repetida, que no es la ficha: en la corrida
// 129876 el nodo recibio {} y perdio hasta el client_id.
// Se adapta el CABLE, no la pieza ajena.
return [{ json: $("Ficha del cliente").first().json }];

// [PLANEACIÓN] Junta de brazos · §7 · «espera a que CONTESTEN, no a que TRAIGAN»
// 🔴 NUNCA aborta. Si fallan todos, el plan se escribe con manual + ficha y los huecos.
// 🔴 Los límites NO están calibrados: se fijan cronometrando la primera corrida real (C3).
//    El corte por tiempo lo hace el nodo HTTP de cada brazo (options.timeout);
//    acá se traduce lo que llegó (o no llegó) a la forma del §4.2.
const MOTIVO_TIEMPO_AGOTADO = 'tiempo agotado';   // sólo si el reloj cortó de verdad
const MOTIVO_NO_LLEGO = 'no llegó a la junta';     // el que no tiene rama, o la tiene apagada
const ESTADOS = ['trajo', 'sin_dato', 'sin_respuesta'];
const ahora = new Date().toISOString();

// El pedido original trae qué brazos se lanzaron y con qué límite (§4.1).
let esperados = [];
try {
  const elegidos = $('elegir brazos').first().json;
  esperados = (elegidos.pedidos || []).map((p) => ({
    brazo: p.brazo, objetivo: p.objetivo, limite_ms: Number(p.limite_ms) || null,
  }));
} catch (e) { esperados = []; }
// 🔴 los BRAZOS pedidos son los nombres DISTINTOS, no la cantidad de pedidos:
// siete objetivos pueden salir de un solo brazo.
const brazosPedidos = {};
for (const e of esperados) { if (e.brazo) brazosPedidos[e.brazo] = true; }

const normalizar = (brazo, objetivo, crudo) => {
  const base = { brazo: brazo, objetivo: objetivo, medido_en: ahora };
  if (crudo && typeof crudo === 'object' && !Array.isArray(crudo) && ESTADOS.indexOf(crudo.estado) !== -1) {
    const est = crudo.estado;
    const out = {
      brazo: typeof crudo.brazo === 'string' ? crudo.brazo : brazo,
      objetivo: typeof crudo.objetivo === 'string' ? crudo.objetivo : objetivo,
      estado: est,
      datos: (crudo.datos && typeof crudo.datos === 'object') ? crudo.datos : {},
      fuente: typeof crudo.fuente === 'string' ? crudo.fuente : null,
      medido_en: typeof crudo.medido_en === 'string' ? crudo.medido_en : ahora,
    };
    // §4.2 · el motivo es obligatorio si no trajo · un hueco mudo es peor que un hueco
    if (est !== 'trajo') out.motivo = typeof crudo.motivo === 'string' ? crudo.motivo : 'el brazo no declaró motivo';
    return out;
  }
  // 🔴 CORREGIDO 2026-09-10 (lo encontró CC#2) · una forma que NO habla el
  // contrato no alcanza para afirmar que alguien miró. Nunca `trajo`.
  const vacio = crudo === null || crudo === undefined ||
    (Array.isArray(crudo) && crudo.length === 0) ||
    (typeof crudo === 'object' && Object.keys(crudo).length === 0);
  if (vacio) return Object.assign(base, { estado: 'sin_respuesta', datos: {}, fuente: null, motivo: 'llegó un item vacío · no alcanza para afirmar que se miró' });
  const claves = (typeof crudo === 'object') ? Object.keys(crudo).slice(0, 6).join(', ') : (typeof crudo);
  return Object.assign(base, { estado: 'sin_respuesta', datos: {}, fuente: null,
    motivo: 'contestó con una forma que no es la del contrato · no se puede afirmar que se miró · claves: ' + claves });
};

const material = [];
const vistos = {};        // OBJETIVOS vistos · sirve para saber quién falta
const brazosVistos = {};  // 🔴 BRAZOS vistos · NO es lo mismo, y ahí estaba el defecto
let sinIdentidad = 0;     // respuestas que llegaron sin nombre de brazo
let pasamanos = 0;
// 🔴 En n8n un nodo APAGADO no se saltea: deja pasar su ENTRADA tal cual. Lo
// que llega por esa rama es el sobre de `elegir brazos` —con `pedidos`— y no
// la respuesta de ningún brazo. Se reconoce por eso: una respuesta de brazo
// JAMÁS trae la lista de pedidos. Antes esto se archivaba como `trajo` y el
// plan habría leído NUESTRA lista de compras como evidencia del cliente.
const esPasamanos = (j) => !!j && typeof j === 'object' && !Array.isArray(j) &&
  ESTADOS.indexOf(j.estado) === -1 && (Array.isArray(j.pedidos) || Array.isArray(j.descartados));
for (const it of $input.all()) {
  const j = it.json || {};
  // el pasamanos NO produce material: no es un brazo. Se cuenta y se declara.
  if (esPasamanos(j)) { pasamanos++; continue; }
  const brazo = j.brazo || (j.body && j.body.brazo) || 'desconocido';
  const objetivo = j.objetivo || (j.body && j.body.objetivo) || 'desconocido';
  // n8n con onError:continueRegularOutput deja el fallo en `error`;
  // con alwaysOutputData y sin salida deja el item vacío.
  if (j.error !== undefined && j.error !== null) {
    const txt = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
    const esTiempo = /timeout|ETIMEDOUT|ESOCKETTIMEDOUT|aborted/i.test(String(txt));
    material.push({ brazo: brazo, objetivo: objetivo, estado: 'sin_respuesta', datos: {}, fuente: null, medido_en: ahora,
      motivo: esTiempo ? (MOTIVO_TIEMPO_AGOTADO + ' · ' + txt) : ('el brazo falló · ' + txt) });
  } else {
    material.push(normalizar(brazo, objetivo, j.respuesta !== undefined ? j.respuesta : j));
  }
  vistos[objetivo] = true;
  // 🔴 CORREGIDO 2026-09-10 · un brazo NO es un objetivo. Un solo brazo puede
  // traer siete objetivos. Y una respuesta anónima no acredita a ningún brazo:
  // se cuenta aparte, no se disimula.
  if (brazo === 'desconocido') sinIdentidad++; else brazosVistos[brazo] = true;
}

// 🔴 el que se lanzó y NO llegó hasta acá también se declara · si no, el hueco
// desaparece y el plan se lee como si nadie lo hubiera pedido.
// 🔴 CORREGIDO 2026-09-10 (2ª vuelta · lo pidió CC#2) · el motivo YA NO ES FIJO.
// La junta sabe tres cosas distintas sobre una ausencia y ahora dice cuál es:
//   ① su brazo SÍ contestó, pero su respuesta no cubrió este objetivo
//      (el abanico manda 1 respuesta por rama y acá se espera 1 por objetivo)
//   ② no contestó nadie con ese nombre, pero llegaron respuestas ANÓNIMAS ⇒
//      no se puede afirmar que su brazo no contestó · se dice el hueco, no la causa
//   ③ no llegó, y no hay anónimas que lo expliquen
// «tiempo agotado» no aparece en ninguna: acá nadie agotó ningún tiempo.
for (const e of esperados) {
  if (vistos[e.objetivo]) continue;
  const limiteComoDato = e.limite_ms ? (' · su límite declarado era ' + e.limite_ms + ' ms') : '';
  let motivo;
  if (brazosVistos[e.brazo]) {
    motivo = 'su brazo contestó, pero su respuesta no cubrió este objetivo' + limiteComoDato;
  } else if (sinIdentidad > 0) {
    motivo = MOTIVO_NO_LLEGO + ' con su nombre · llegaron ' + sinIdentidad +
      ' respuesta(s) sin identidad, así que NO se puede afirmar que su brazo no contestó' + limiteComoDato;
  } else {
    motivo = MOTIVO_NO_LLEGO + ' · no se puede saber si tardó, si su rama está apagada, o si nunca se cableó' + limiteComoDato;
  }
  material.push({ brazo: e.brazo, objetivo: e.objetivo, estado: 'sin_respuesta', datos: {}, fuente: null, medido_en: ahora,
    motivo: motivo });
}

const huecos = {
  sin_dato: material.filter((m) => m.estado === 'sin_dato').map((m) => m.objetivo),
  sin_respuesta: material.filter((m) => m.estado === 'sin_respuesta').map((m) => m.objetivo),
};

// 🔴 SIEMPRE devuelve un item. Nunca `throw`, nunca `return []`.
return [{ json: {
  material: material,
  huecos: huecos,
  ningun_brazo_trajo: material.every((m) => m.estado !== 'trajo'),
  // 🔴 CORREGIDO 2026-09-10 (2ª vuelta · lo encontró CC#2) · antes estos dos
  // números contaban OBJETIVOS y los llamaban BRAZOS. Con siete pedidos a un
  // solo brazo, el plan habría leído «siete brazos contestaron» cuando era UNO.
  // Un número mal rotulado es peor que ningún número: se lee como evidencia.
  objetivos_pedidos: esperados.length,
  objetivos_que_contestaron: Object.keys(vistos).filter((o) => o !== 'desconocido').length,
  brazos_pedidos: Object.keys(brazosPedidos).length,
  brazos_que_contestaron: Object.keys(brazosVistos).length,
  // 🔴 el anonimato se DECLARA · el arreglo del cable es de CC#2, pero mientras
  // llegue una respuesta sin nombre, este número tiene que verse.
  respuestas_sin_identidad: sinIdentidad,
  // 🔴 el pasamanos se DECLARA · si una rama está apagada, que se vea
  ramas_apagadas_o_pasamanos: pasamanos,
  limites_sin_calibrar: true,
} }];

// PEGAMENTO (CC#2 · C2) · NO es una de las cinco piezas.
//
// 🔴 EL DERIVADOR EMITE `dinero` Y EL REDACTOR LEE `plata`. Dos piezas, dos
//    manos, dos nombres para la misma cosa. Sin este puente la cadena del
