//    calla. Hay que canonizar UN nombre; el puente lo declara, no lo tapa.
//
// Y trae lo que el redactor (§4.3) espera y la cadena no le acerca sola.
const e = $input.first().json || {};
const noTraido = [];
const dame = (nom, campo) => {
  try { return $(nom).first().json; }
  catch (x) { noTraido.push(campo + " · no se pudo leer el nodo " + nom + " · " + x.message); return null; }
};
const ficha = dame("Ficha del cliente", "ficha") || {};
const guarda = dame("① GUARDA · sin manual aprobado se DETIENE", "manual") || {};
const elegidos = dame("elegir brazos", "descartados") || {};
