const esPasamanos = (j) => !!j && typeof j === 'object' && !Array.isArray(j) &&
  ESTADOS.indexOf(j.estado) === -1 && (Array.isArray(j.pedidos) || Array.isArray(j.descartados));

const salida = [];
const abrirPorObjetivo = (base) => {
  for (const objetivo of objetivos) salida.push({ json: Object.assign({}, base, { brazo: BRAZO, objetivo: objetivo }) });
};

for (const it of $input.all()) {
  const j = it.json || {};
  if (esPasamanos(j)) { salida.push({ json: j }); continue; }
  // 🔴 si no hay objetivos, no hay material · también en el camino de ÉXITO.
  // Con las puertas en 404 todo caía por el camino del fallo y el agujero no se
  // veía; publicadas, la rama sin pedidos recibe un «pedidos vino vacío» bien
  // formado y se firmaba con un objetivo inventado (corrida 130108: 7 de 7
  // objetivos y 3 brazos, cuando eran 6 y 2). Lo encontró CC#1.
  if (!objetivos.length) continue;
  if (Object.keys(j).length === 0) {
    abrirPorObjetivo({ error: 'la rama contestó con un item vacío · no alcanza para afirmar que se miró' });
    continue;
  }
  if (j.error !== undefined && j.error !== null) { abrirPorObjetivo({ error: j.error }); continue; }
  const cuerpo = Array.isArray(j.respuestas) ? j.respuestas : [j];
  for (const r of cuerpo) {
    const p = r || {};
    salida.push({ json: Object.assign({}, p, {
      brazo: (typeof p.brazo === 'string' && p.brazo) ? p.brazo : BRAZO,
      objetivo: (typeof p.objetivo === 'string' && p.objetivo) ? p.objetivo
        : (objetivos.length === 1 ? objetivos[0] : '(la puerta no dijo de qué objetivo hablaba)'),
    }) });
  }
}

if (!salida.length) abrirPorObjetivo({ error: 'la rama no produjo ningún item' });
return salida;

// 🔴 UNA CORRIDA SIN PDF NO PUEDE SALIR EXITOSA (2026-09-12 · CC#3)
//
// Ahora hay TRES cosas que pueden faltar, y se dicen por separado:
//   la vuelta del redactor · el guardado del plan · el PDF
// El guardado va ANTES de Drive a propósito: si Drive falla, el plan NO se pierde
// (medido el 12-sep: un plan de 22.060 caracteres se perdió entero porque nadie
// lo había guardado · el registro de invocaciones sólo conserva 2.000).
const v = $('¿Llegó la vuelta?').first().json;
const texto = String(v.texto || '');
const hayPlan = texto.trim().length > 0;

let guardado = false, guardado_id = null;
try {
  const g = $('Guardar el plan').first().json;
  const gb = (g && g.body) ? g.body : g;
  const fila = Array.isArray(gb) ? gb[0] : gb;
  guardado = !!(fila && fila.id);
  guardado_id = fila && fila.id || null;
} catch (x) { guardado = false; }

let rec = null;
try { const d = $('Plan → Drive (PDF)').first().json; rec = (d && d.body) ? d.body : d; } catch (x) { rec = null; }
const hayPdf = !!(rec && rec.ok === true && rec.file_id);

const problemas = [];
if (!hayPlan) problemas.push(v.motivo || 'el redactor no devolvió texto');
if (hayPlan && !guardado) problemas.push('el plan NO quedó guardado · si Drive falla se pierde');
if (!hayPdf) problemas.push(hayPlan
  ? ('Drive no devolvió un archivo (' + String((rec && rec.motivo) || 'sin motivo') + ')')
  : 'no se llamó a Drive porque no había plan que escribir');

return [{ json: {
  ok: problemas.length === 0,
  llego_la_vuelta: v.llego_la_vuelta === true,
  hay_plan: hayPlan,
  caracteres_del_plan: texto.length,
  plan_guardado: guardado,
  plan_guardado_id: guardado_id,
  hay_pdf: hayPdf,
  file_id: rec && rec.file_id || null,
  url: rec && rec.url || null,
  carpeta: rec && rec.folder_id || null,
  problemas: problemas,
  client_id: v.client_id,
  client_name: v.client_name,
} }];

// 🔴 EL AVISO DICE QUÉ HACER · no sólo que falló.
const r = $input.first().json;
const pasos = [];
if (!r.llego_la_vuelta) {
  pasos.push('1) la vuelta NO llegó · el plan PUEDE estar escrito: mirá agent_invocations por client_id y fijate response_length');
  pasos.push('2) si response_length es grande, el texto completo NO está en la base (guarda 2.000) · buscalo en Braintrust por session_id');
  pasos.push('3) comprobá el saldo del proveedor ANTES de reintentar · y NO repagues el raspado: reusá el pedido que armó «Redactor (B4)»');
} else if (!r.plan_guardado) {
  pasos.push('1) el plan llegó (' + r.caracteres_del_plan + ' caracteres) pero NO se guardó · revisá los permisos de client_historical_outputs');
  pasos.push('2) el texto está en esta corrida de n8n · copialo de «¿Llegó la vuelta?» antes de que caduque el historial (~4 h)');
} else {
  pasos.push('1) el plan está guardado (' + String(r.plan_guardado_id).slice(0, 8) + '…) · NO hay que volver a pagar al redactor');
  pasos.push('2) lo que falló es Drive · mirá la credencial de Google en n8n · caduca cada 7 días si la app OAuth no está publicada');
  pasos.push('3) reintentá sólo Drive: POST a /webhook/zero-risk/texto-a-drive con client_id, client_name, nombre y el texto guardado');
}
return [{ json: {
  texto: ':rotating_light: *Plan sin PDF* — la corrida de planeación terminó sin documento en Drive.\n' +
    '• cliente: `' + String(r.client_name || r.client_id || '?') + '`\n' +
    '• qué falló: ' + r.problemas.join(' · ') + '\n' +
    '• plan escrito: ' + (r.hay_plan ? (r.caracteres_del_plan + ' caracteres') : 'NO') +
    ' · guardado: ' + (r.plan_guardado ? 'SÍ' : 'NO') + '\n' +
    '*Qué hacer:*\n' + pasos.map((p) => '  ' + p).join('\n'),
} }];

// 🔴 ¿LLEGÓ LA VUELTA, O SE AGOTÓ LA ESPERA? (2026-09-12 · CC#3)
//
// El nodo Wait sigue por la MISMA salida en los dos casos: si el redactor contesta
// y si nadie contesta nunca. Sin esta distinción, una espera agotada se ve igual
// que una vuelta vacía — y la corrida se iría diciendo «exitosa» sin plan.
//
// Medido el 12-sep, las dos formas de perder el plan con la espera colgada:
//   · el redactor tardó 341 s y mi nodo cortó a los 290 s  → plan escrito y tirado
//   · el corredor se reinició y devolvió 502 a los 301,7 s → plan perdido
// La vuelta arregla las dos. Esto cubre la tercera: que la vuelta NO llegue.
const e = $input.first().json || {};
const cuerpo = e.body ? e.body : e;
const texto = String(cuerpo.response || cuerpo.result || cuerpo.output || cuerpo.text || '');

// la vuelta trae cuerpo con texto · la espera agotada llega vacía o sin él
const llego = texto.trim().length > 0;

let cid = null, cnom = null;
try { cid = $('Redactor (B4)').first().json.cliente_id; } catch (x) { /* */ }
try { cnom = $('Ficha del cliente').first().json.name; } catch (x) { /* */ }

return [{ json: {
  llego_la_vuelta: llego,
  texto: texto,
  caracteres: texto.length,
  client_id: cid,
  client_name: cnom,
  motivo: llego ? null
    : 'la vuelta del redactor NO llegó · se agotó la espera · el plan puede haberse escrito igual y estar en el corredor · NO se da por exitosa',
} }];

// [PLANEACIÓN] ② GUARDA · sin referencia del producto se DETIENE · E16 · 2026-09-12
//
// 🔴 POR QUÉ ES UN NODO APARTE Y NO UNA LÍNEA ADENTRO DEL REDACTOR:
// el nodo `Redactor (B4)` tiene `onError: continueRegularOutput` — se traga sus
// propios errores. Un `throw` adentro NO detiene nada: la corrida seguiría hasta
// `Pedir el plan al redactor` y pagaría igual. Lo probé antes de publicarlo.
// Este nodo NO lleva `onError`: el que falla acá, detiene. Mismo patrón que la
// guarda del manual de marca, que es la otra cosa sin la cual no hay plan.
//
// ⚠️ NO CONTRADICE LA REGLA 0 DE EMILIO: un dato del NEGOCIO que falta (precio,
// costos, presupuesto) NO bloquea · se declara el hueco y el plan sale igual.
// Esto es el CONTRATO del producto: sin las ocho secciones no hay plan, hay
// redacción libre. Material faltante ⇒ se declara. Escritura rota ⇒ se detiene.
const REFERENCIA_MINIMA = 2000;
const entrada = ($input.first() && $input.first().json) || {};
const ref = String(entrada.referencia || '').trim();
const loQueDiceElPuente = String((entrada.puente_declara || {}).referencia || 'el puente no declaró nada');
if (ref.length < REFERENCIA_MINIMA) {
  throw new Error('PLANEACION_REFERENCIA_VACIA · el documento de referencia del producto llegó con '
    + ref.length + ' caracteres (mínimo ' + REFERENCIA_MINIMA + ') · sin las ocho secciones el plan no'
    + ' tiene estructura pedida y el redactor escribiría a criterio propio · la corrida SE DETIENE'
    + ' antes de invocar y NO se gasta · lo que dice el puente: ' + loQueDiceElPuente);
}
// 🟢 pasa tal cual · una guarda no transforma lo que deja pasar
return $input.all();
